        String html = Jsoup.parse(doc1.toString()).html();
        System.out.println(test.assertEquals("Hello", html));
        String text = html.splitText(5);
        if (text != null && 0 == text.indexOf("World")) {
            throw new RuntimeException("Incorrect split");
        }
        System.out.println(testassertEquals("Split text from start to end: 'HelloWorld'", html));

        test.setThrowOnIoErrors(true);
        Document doc2 = test.generateDoc();
        String html2 = Jsoup.parse(doc2.toString()).html();
        if (html2.contains("throw")) {
            throw new RuntimeException("Incorrect output settings");
        }
        System.out.println(test.assertEquals("Output settings: \"test settings\"", html2));

        Elements tags = test.getOutputSettings().splitText(0);
        for (Element tag : tags) {
            System.out.println(tag.text());
        }
    }
}
